CREATE OR REPLACE FUNCTION public.save_threadwise_workspace(p_id uuid,p_title text,p_document jsonb,p_revision bigint) RETURNS SETOF public.workspaces LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF p_revision = -1 THEN RETURN QUERY INSERT INTO public.workspaces(id,user_id,title,document,revision) VALUES(p_id,auth.uid(),p_title,p_document,0) ON CONFLICT DO NOTHING RETURNING *; ELSE RETURN QUERY UPDATE public.workspaces SET title=p_title,document=p_document,revision=revision+1,updated_at=now() WHERE id=p_id AND user_id=auth.uid() AND revision=p_revision RETURNING *; IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=p_id AND user_id=auth.uid()) THEN RETURN QUERY INSERT INTO public.workspaces(id,user_id,title,document,revision) VALUES(p_id,auth.uid(),p_title,p_document,0) ON CONFLICT DO NOTHING RETURNING *; END IF; END IF; END; $$;
GRANT EXECUTE ON FUNCTION public.save_threadwise_workspace(uuid,text,jsonb,bigint) TO authenticated;
CREATE TABLE public.workshop_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),host_id uuid NOT NULL,title text NOT NULL DEFAULT 'Thinking together',join_code text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(16),'hex'),phase text NOT NULL DEFAULT 'setup' CHECK(phase IN ('setup','silent','discuss','vote','closed')),ends_at timestamptz,vote_budget integer NOT NULL DEFAULT 3 CHECK(vote_budget BETWEEN 1 AND 20),cards jsonb NOT NULL DEFAULT '[]',groups jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.workshop_sessions TO authenticated; GRANT ALL ON public.workshop_sessions TO service_role;
ALTER TABLE public.workshop_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.workshop_members(session_id uuid NOT NULL REFERENCES public.workshop_sessions(id) ON DELETE CASCADE,user_id uuid NOT NULL,display_name text NOT NULL DEFAULT 'Participant',PRIMARY KEY(session_id,user_id));
GRANT SELECT ON public.workshop_members TO authenticated; GRANT ALL ON public.workshop_members TO service_role;
ALTER TABLE public.workshop_members ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.workshop_access(p_session uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (EXISTS(SELECT 1 FROM public.workshop_sessions WHERE id=p_session AND host_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.workshop_members WHERE session_id=p_session AND user_id=auth.uid())); $$;
REVOKE ALL ON FUNCTION public.workshop_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.workshop_access(uuid) TO authenticated;
CREATE POLICY workshop_read ON public.workshop_sessions FOR SELECT TO authenticated USING(public.workshop_access(id));
CREATE POLICY workshop_create ON public.workshop_sessions FOR INSERT TO authenticated WITH CHECK(host_id=auth.uid());
CREATE POLICY workshop_host_update ON public.workshop_sessions FOR UPDATE TO authenticated USING(host_id=auth.uid()) WITH CHECK(host_id=auth.uid());
CREATE POLICY workshop_member_read ON public.workshop_members FOR SELECT TO authenticated USING(public.workshop_access(session_id));
CREATE TABLE public.workshop_ideas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.workshop_sessions(id) ON DELETE CASCADE,user_id uuid NOT NULL,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 500),body text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.workshop_ideas TO authenticated; GRANT ALL ON public.workshop_ideas TO service_role;
ALTER TABLE public.workshop_ideas ENABLE ROW LEVEL SECURITY;
CREATE POLICY workshop_idea_read ON public.workshop_ideas FOR SELECT TO authenticated USING(public.workshop_access(session_id) AND (user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.workshop_sessions WHERE id=session_id AND phase IN ('discuss','vote','closed'))));
CREATE POLICY workshop_idea_create ON public.workshop_ideas FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.workshop_access(session_id) AND EXISTS(SELECT 1 FROM public.workshop_sessions WHERE id=session_id AND phase='silent'));
CREATE TABLE public.workshop_votes(session_id uuid NOT NULL REFERENCES public.workshop_sessions(id) ON DELETE CASCADE,user_id uuid NOT NULL,node_id text NOT NULL,dots integer NOT NULL CHECK(dots BETWEEN 1 AND 20),PRIMARY KEY(session_id,user_id,node_id));
GRANT SELECT ON public.workshop_votes TO authenticated; GRANT ALL ON public.workshop_votes TO service_role;
ALTER TABLE public.workshop_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY workshop_votes_read ON public.workshop_votes FOR SELECT TO authenticated USING(public.workshop_access(session_id));
CREATE OR REPLACE FUNCTION public.join_workshop(p_code text,p_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to join'; END IF; SELECT id INTO sid FROM public.workshop_sessions WHERE join_code=trim(p_code) AND phase<>'closed'; IF sid IS NULL THEN RAISE EXCEPTION 'Session not found or closed'; END IF; INSERT INTO public.workshop_members(session_id,user_id,display_name) VALUES(sid,auth.uid(),left(coalesce(nullif(trim(p_name),''),'Participant'),80)) ON CONFLICT(session_id,user_id) DO UPDATE SET display_name=EXCLUDED.display_name; RETURN sid; END; $$;
REVOKE ALL ON FUNCTION public.join_workshop(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.join_workshop(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.cast_workshop_vote(p_session uuid,p_node text,p_delta integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE room public.workshop_sessions; used integer; current_dots integer; BEGIN IF auth.uid() IS NULL OR NOT public.workshop_access(p_session) THEN RAISE EXCEPTION 'Not a participant'; END IF; IF p_delta NOT IN (-1,1) THEN RAISE EXCEPTION 'Invalid vote'; END IF; SELECT * INTO room FROM public.workshop_sessions WHERE id=p_session FOR UPDATE; IF room.phase<>'vote' THEN RAISE EXCEPTION 'Voting is not open'; END IF; IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(room.cards) c WHERE c->>'id'=p_node) AND NOT EXISTS(SELECT 1 FROM public.workshop_ideas WHERE id::text=p_node AND session_id=p_session) THEN RAISE EXCEPTION 'Card not in session'; END IF; SELECT coalesce(sum(dots),0) INTO used FROM public.workshop_votes WHERE session_id=p_session AND user_id=auth.uid(); SELECT coalesce(dots,0) INTO current_dots FROM public.workshop_votes WHERE session_id=p_session AND user_id=auth.uid() AND node_id=p_node; current_dots:=coalesce(current_dots,0); IF p_delta=1 AND used>=room.vote_budget THEN RAISE EXCEPTION 'All dots used'; END IF; IF p_delta=-1 AND current_dots=0 THEN RETURN; END IF; IF current_dots+p_delta=0 THEN DELETE FROM public.workshop_votes WHERE session_id=p_session AND user_id=auth.uid() AND node_id=p_node; ELSE INSERT INTO public.workshop_votes(session_id,user_id,node_id,dots) VALUES(p_session,auth.uid(),p_node,current_dots+p_delta) ON CONFLICT(session_id,user_id,node_id) DO UPDATE SET dots=EXCLUDED.dots; END IF; END; $$;
REVOKE ALL ON FUNCTION public.cast_workshop_vote(uuid,text,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cast_workshop_vote(uuid,text,integer) TO authenticated;